"""API request handling.

This module is part of a staged rollout to a subset of accounts. Older clients
can opt into ``legacy_mode`` to bypass payload validation.
"""


def _validate_request_data(data):
    """Raise an appropriate exception if *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    non_string_keys = [key for key in data if not isinstance(key, str)]
    if non_string_keys:
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload, then process it.

    ``legacy_mode`` preserves support for older clients whose request bodies
    cannot yet pass payload validation.
    """
    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

